#include <bits/stdc++.h>
using namespace std;

int main() {
	// your code goes here
    int t;
    cin >> t;
    while(t--){
        int n,m;
        cin >> n >> m;
        vector<int> a(m);
        for(int i=0;i<m;++i){
            cin >> a[i];
        }
        sort(a.begin(),a.end());
        int diff=0;
        for(int i=0;i<a.size()-1;++i){
            diff=max(a[i+1]-a[i]-1,diff);
        }
        
        // cout << diff << "\n";
        
        int lgap=a[0]-1;
        int rgap=n-a[m-1];
        
        // cout << lgap << " " << rgap << " " << diff << "\n"; 
        
        cout << 2*min(lgap,rgap) + max(lgap,rgap) + max(0,diff - lgap - rgap) << "\n";
        // cout << a[1]-a[0] + n-a[m-2] + diff/2 << "\n";
        
    }
}
